/* @lc app=leetcode id=2157 lang=kotlin */
class Solution {
    fun groupStrings(words: Array<String>) = words.map { w -> w.fold(0) { a, c -> a or (1 shl (c - 'a')) } }.groupingBy { it }.eachCount().let { cnt -> mutableMapOf<Int, Int>().let { parent -> kotlin.DeepRecursiveFunction<Int, Int> { i -> parent[i]?.takeIf { it != i }?.let { callRecursive(it).also { r -> parent[i] = r } } ?: i.also { parent[i] = it } }.let { find -> cnt.keys.map { m -> (0 until 26).map { i -> (m xor (1 shl i)).let { d -> (if (d in cnt) find(m).let { r1 -> find(d).let { r2 -> if (r1 != r2) parent.put(r1, r2) else Unit } } else Unit).run { if ((m shr i) and 1 == 1) (0 until 26).map { j -> (d xor (1 shl j)).let { r -> if ((d shr j) and 1 == 0 && r in cnt) find(m).let { r1 -> find(r).let { r2 -> if (r1 != r2) parent.put(r1, r2) else Unit } } else Unit } } else Unit } } } }.run { cnt.entries.groupBy { find(it.key) }.let { g -> intArrayOf(g.size, g.values.maxOfOrNull { it.sumOf { e -> e.value } } ?: 0) } } } }
}